<?php
declare(strict_types=1);
require_once __DIR__.'/auth.php';require_login();$pdo=db();
if(!user_can('settings.manage')){http_response_code(403);die('Access denied.');}
if(!table_exists($pdo,'custom_fields'))redirect('upgrade_phase5.php');
$msg=flash('success');
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=post_string('field_name');$label=post_string('field_label');if($name===''||$label===''){flash('success','Field name and label are required.');redirect('customizer.php');}try{$st=$pdo->prepare('INSERT INTO custom_fields(entity_type,field_name,field_label,field_type,options_json,is_required,sort_order) VALUES("client",?,?,?,?,?,?)');$options=[];$raw=post_string('options');if($raw!=='')$options=array_values(array_filter(array_map('trim',preg_split('/\r?\n/',$raw))));$st->execute([$name,$label,post_string('field_type','text'),$options?$options:null,isset($_POST['is_required'])?1:0,post_int('sort_order')]);$id=(int)$pdo->lastInsertId();activity($pdo,'create','customizer',$id,'Client custom field created: '.$label);flash('success','Custom field created.');}catch(Throwable $e){error_log('[SPS CUSTOMIZER] '.$e->getMessage());flash('success','Field could not be created. The field name may already exist.');}redirect('customizer.php');}
$rows=$pdo->query("SELECT * FROM custom_fields WHERE entity_type='client' ORDER BY sort_order,id")->fetchAll();
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Customizer · SPS CRM</title><style>body{margin:0;background:#f5f7fb;font-family:Arial;color:#172033}.top{background:#fff;border-bottom:1px solid #e5eaf2;padding:18px 28px;display:flex;justify-content:space-between}.top a{color:#315ee7;text-decoration:none}.wrap{max-width:1050px;margin:auto;padding:28px}.grid{display:grid;grid-template-columns:1fr 1.6fr;gap:16px}.card{background:#fff;border:1px solid #e5eaf2;border-radius:15px;padding:20px}.field{margin:10px 0}.field label{display:block;font-size:12px;font-weight:bold;margin-bottom:6px}.field input,.field select,.field textarea{width:100%;padding:10px;border:1px solid #d8dfeb;border-radius:8px}.btn{background:#315ee7;color:#fff;border:0;padding:10px 13px;border-radius:8px;font-weight:bold}.table{width:100%;border-collapse:collapse}.table th,.table td{padding:11px;border-bottom:1px solid #edf0f5;text-align:left;font-size:13px}.success{background:#ebf9f1;color:#176a3c;padding:10px;border-radius:8px;margin-bottom:14px}@media(max-width:780px){.grid{grid-template-columns:1fr}}</style></head><body><header class="top"><strong>SPS CRM · Customizer</strong><a href="dashboard.php">← Dashboard</a></header><main class="wrap"><?php if($msg):?><div class="success"><?=e($msg)?></div><?php endif;?><div class="grid"><div class="card"><h2>Client Field</h2><form method="post"><?=csrf_field()?><div class="field"><label>Field Name</label><input name="field_name" placeholder="preferred_contact"></div><div class="field"><label>Field Label</label><input name="field_label" placeholder="Preferred Contact"></div><div class="field"><label>Type</label><select name="field_type"><option>text</option><option>textarea</option><option>number</option><option>currency</option><option>email</option><option>phone</option><option>date</option><option>dropdown</option><option>checkbox</option></select></div><div class="field"><label>Dropdown Options (one per line)</label><textarea name="options"></textarea></div><label><input type="checkbox" name="is_required"> Required</label><div class="field"><label>Sort Order</label><input name="sort_order" type="number" value="0"></div><button class="btn">Create Field</button></form></div><div class="card"><h2>Client Custom Fields</h2><table class="table"><tr><th>Label</th><th>Name</th><th>Type</th><th>Required</th><th>Order</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['field_label'])?></td><td><?=e($r['field_name'])?></td><td><?=e($r['field_type'])?></td><td><?=($r['is_required']?'Yes':'No')?></td><td><?=e($r['sort_order'])?></td></tr><?php endforeach;?></table></div></div></main></body></html>
